  {
    Scanner sc = new Scanner (new File ("wordsearch.dat"));
    int n = sc.nextInt();
    String line = sc.nextLine();

    char[][] a = new char[n][n];  // grid of characters
    for (int i = 0; i < n; i++)
    {
      line = sc.nextLine();
      String[] letters = line.split("\\s+");
      for (int j = 0; j < letters.length; j++)
      {
